CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,pass TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lots(id INTEGER PRIMARY KEY,name TEXT NOT NULL,lat REAL NOT NULL,lng REAL NOT NULL,rate INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bays(lot_id INTEGER NOT NULL REFERENCES lots(id),num INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'free',updated_at TEXT,PRIMARY KEY(lot_id,num));
CREATE TABLE IF NOT EXISTS bookings(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),lot_id INTEGER NOT NULL,bay_num INTEGER NOT NULL,plate TEXT NOT NULL,hours INTEGER NOT NULL,amount INTEGER NOT NULL,method TEXT NOT NULL,last4 TEXT,pay_ref TEXT,status TEXT NOT NULL DEFAULT 'active',arrived_at TEXT,created_at TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plate_events(id INTEGER PRIMARY KEY,lot_id INTEGER NOT NULL,plate TEXT NOT NULL,kind TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS gpu_stats(id INTEGER PRIMARY KEY,lot_id INTEGER NOT NULL,fps REAL,latency_ms REAL,util REAL,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_book ON bookings(user_id,status);
